@page "/apply"
@rendermode InteractiveServer
@using sv_8690d87f9fae4e8bba8421d8cd63f448.Models
@using sv_8690d87f9fae4e8bba8421d8cd63f448.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        <h3>✓ Application Submitted Successfully!</h3>
        <p>Your application ID is: <strong>@_applicationId</strong></p>
        <p>Thank you for applying. We will review your application and get back to you.</p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="step-indicator mb-4">
        <ol class="step-list">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var stepClass = GetStepClass(stepIndex);
                <li class="step-item @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                    <span class="step-badge">
                        @if (IsStepCompleted(stepIndex))
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <span class="step-label">@_stepNames[stepIndex]</span>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <div class="card">
            <div class="card-header"><h4>Personal Information</h4></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="_fullName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="_phone" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Address <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="_address" />
                </div>
                <div class="d-flex justify-content-end">
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                        @if (_isValidating)
                        {
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next</span>
                        }
                    </button>
                </div>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <div class="card">
            <div class="card-header"><h4>Work History</h4></div>
            <div class="card-body">
                @for (int i = 0; i < _workEntries.Count; i++)
                {
                    var index = i;
                    <div class="border rounded p-3 mb-3">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5>Position @(index + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" value="@_workEntries[index].Company"
                                    @onchange="(e) => UpdateWorkEntry(index, _workEntries[index] with { Company = e.Value?.ToString() ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" value="@_workEntries[index].Title"
                                    @onchange="(e) => UpdateWorkEntry(index, _workEntries[index] with { Title = e.Value?.ToString() ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@FormatDate(_workEntries[index].StartDate)"
                                    @onchange="(e) => UpdateWorkEntry(index, _workEntries[index] with { StartDate = ParseDate(e.Value?.ToString()) })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" value="@FormatDate(_workEntries[index].EndDate)"
                                    disabled="@_workEntries[index].IsCurrent"
                                    @onchange="(e) => UpdateWorkEntry(index, _workEntries[index] with { EndDate = ParseNullableDate(e.Value?.ToString()) })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end">
                                <div class="form-check mb-2">
                                    <input type="checkbox" class="form-check-input" id="current-@index" checked="@_workEntries[index].IsCurrent"
                                        @onchange="(e) => UpdateWorkEntry(index, _workEntries[index] with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : _workEntries[index].EndDate })" />
                                    <label class="form-check-label" for="current-@index">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="2" value="@_workEntries[index].Description"
                                @onchange="(e) => UpdateWorkEntry(index, _workEntries[index] with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
                        </div>
                    </div>
                }
                <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (_currentStep == 2)
    {
        <div class="card">
            <div class="card-header"><h4>References</h4></div>
            <div class="card-body">
                @for (int i = 0; i < _references.Count; i++)
                {
                    var index = i;
                    <div class="border rounded p-3 mb-3">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5>Reference @(index + 1)</h5>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" value="@_references[index].Name"
                                    @onchange="(e) => UpdateReference(index, _references[index] with { Name = e.Value?.ToString() ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" value="@_references[index].Relationship"
                                    @onchange="(e) => UpdateReference(index, _references[index] with { Relationship = e.Value?.ToString() ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@_references[index].Email"
                                    @onchange="(e) => UpdateReference(index, _references[index] with { Email = e.Value?.ToString() ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@_references[index].Phone"
                                    @onchange="(e) => UpdateReference(index, _references[index] with { Phone = e.Value?.ToString() ?? string.Empty })" />
                            </div>
                        </div>
                    </div>
                }
                @if (_references.Count < 3)
                {
                    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
                }
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (_currentStep == 3)
    {
        <div class="card">
            <div class="card-header"><h4>Cover Letter</h4></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Write your cover letter</label>
                    <textarea class="form-control" rows="10" maxlength="2000" @bind="_coverLetter" @bind:event="oninput"></textarea>
                    <div class="form-text text-end">@_coverLetter.Length / 2000 characters</div>
                </div>
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (_currentStep == 4)
    {
        <div class="card">
            <div class="card-header"><h4>Review & Submit</h4></div>
            <div class="card-body">
                <!-- Personal Info Summary -->
                <div class="mb-4">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Personal Information</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
                <hr />

                <!-- Work History Summary -->
                <div class="mb-4">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Work History</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="ms-3 mb-2">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <small class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </small>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 mt-1">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
                <hr />

                <!-- References Summary -->
                <div class="mb-4">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>References</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var r in _references)
                    {
                        <div class="ms-3 mb-2">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            <small>@r.Email | @r.Phone</small>
                        </div>
                    }
                </div>
                <hr />

                <!-- Cover Letter Summary -->
                <div class="mb-4">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Cover Letter</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="ms-3" style="white-space: pre-wrap;">@_coverLetter</p>
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        </div>
    }
}

<style>
    .step-list {
        display: flex;
        list-style: none;
        padding: 0;
        margin: 0;
        justify-content: space-between;
    }
    .step-item {
        display: flex;
        flex-direction: column;
        align-items: center;
        flex: 1;
        position: relative;
        cursor: default;
    }
    .step-item.completed {
        cursor: pointer;
    }
    .step-badge {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        margin-bottom: 4px;
        background-color: #e9ecef;
        color: #6c757d;
    }
    .step-item.active .step-badge {
        background-color: #0d6efd;
        color: white;
    }
    .step-item.completed .step-badge {
        background-color: #198754;
        color: white;
    }
    .step-item.dimmed .step-label {
        color: #adb5bd;
    }
    .step-label {
        font-size: 0.8rem;
        text-align: center;
    }
</style>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep = 0;
    private int _highestCompletedStep = -1;
    private string _errorMessage = string.Empty;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string _coverLetter = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (step <= _highestCompletedStep) return "completed";
        return "dimmed";
    }

    private bool IsStepCompleted(int step) => step <= _highestCompletedStep && step != _currentStep;

    private void NavigateToStep(int step)
    {
        if (step <= _highestCompletedStep)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
        _errorMessage = string.Empty;
    }

    private async Task NextStep()
    {
        _errorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isValidating = true;
            StateHasChanged();
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;
            if (!emailValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
        }

        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;

        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _errorMessage = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default)
                    {
                        _errorMessage = "Company name, job title, and start date are required for each position.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        _errorMessage = "All reference fields are required.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                {
                    _errorMessage = "Please write a cover letter.";
                    return false;
                }
                break;
        }
        return true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, WorkEntryModel entry) => _workEntries[index] = entry;

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceModel reference) => _references[index] = reference;

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;
        StateHasChanged();

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workHistory = new WorkHistory(_workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, references, _coverLetter);

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _isSubmitting = false;
        _submitted = true;
    }

    private string FormatDate(DateTime date) => date == default ? string.Empty : date.ToString("yyyy-MM-dd");
    private string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;
    private DateTime ParseDate(string? value) => DateTime.TryParse(value, out var d) ? d : default;
    private DateTime? ParseNullableDate(string? value) => DateTime.TryParse(value, out var d) ? d : null;

    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

