<style>
    .step-list {
        display: flex;
        list-style: none;
        padding: 0;
        margin: 0;
        justify-content: space-between;
    }
    .step-item {
        display: flex;
        flex-direction: column;
        align-items: center;
        flex: 1;
        position: relative;
        cursor: default;
    }
    .step-item.completed {
        cursor: pointer;
    }
    .step-badge {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        margin-bottom: 4px;
        background-color: #e9ecef;
        color: #6c757d;
    }
    .step-item.active .step-badge {
        background-color: #0d6efd;
        color: white;
    }
    .step-item.completed .step-badge {
        background-color: #198754;
        color: white;
    }
    .step-item.dimmed .step-label {
        color: #adb5bd;
    }
    .step-label {
        font-size: 0.8rem;
        text-align: center;
    }
</style>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep = 0;
    private int _highestCompletedStep = -1;
    private string _errorMessage = string.Empty;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string _coverLetter = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (step <= _highestCompletedStep) return "completed";
        return "dimmed";
    }

    private bool IsStepCompleted(int step) => step <= _highestCompletedStep && step != _currentStep;

    private void NavigateToStep(int step)
    {
        if (step <= _highestCompletedStep)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
        _errorMessage = string.Empty;
    }

    private async Task NextStep()
    {
        _errorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isValidating = true;
            StateHasChanged();
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;
            if (!emailValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
        }

        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;

        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _errorMessage = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default)
                    {
                        _errorMessage = "Company name, job title, and start date are required for each position.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        _errorMessage = "All reference fields are required.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                {
                    _errorMessage = "Please write a cover letter.";
                    return false;
                }
                break;
        }
        return true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, WorkEntryModel entry) => _workEntries[index] = entry;

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceModel reference) => _references[index] = reference;

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;
        StateHasChanged();

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workHistory = new WorkHistory(_workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, references, _coverLetter);

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _isSubmitting = false;
        _submitted = true;
    }

    private string FormatDate(DateTime date) => date == default ? string.Empty : date.ToString("yyyy-MM-dd");
    private string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;
    private DateTime ParseDate(string? value) => DateTime.TryParse(value, out var d) ? d : default;
    private DateTime? ParseNullableDate(string? value) => DateTime.TryParse(value, out var d) ? d : null;

    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

